	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * ws.weights[i]
		}
	}

	// Post-scoring: penalize instances with load much above minimum
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		excess := float64(el - minLoad)
		if excess > 0 {
			// Quadratic penalty for load above minimum
			pen := 1.0 / (1.0 + 0.15*excess*excess)
			scores[snap.ID] *= (0.1 + 0.9*pen)
		}
		// Memory pressure guard
		if snap.KVUtilization > 0.85 {
			scores[snap.ID] *= 0.6
		}
	}

	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
	// EVOLVE-BLOCK-END

	// Notify observers of routing decision (stateful scorers update their state)
	for _, obs := range ws.observers {
		obs(req, snapshots[bestIdx].ID)
	}

